<div class="page-title"><div><em>CUSTOMER PROFILE</em><h1><?=html_escape($customer['first_name'].' '.$customer['last_name'])?></h1><p><?=html_escape($customer['email'])?> · <?=html_escape($customer['phone'])?></p></div><span class="<?=status_class($customer['status'])?>"><?=ucfirst($customer['status'])?></span></div><section class="panel admin-actions"><div><h3>Account access</h3><?=form_open('admin/customers/'.$customer['id'].'/status',array('class'=>'inline-controls'))?><select name="status"><option value="active" <?=$customer['status']==='active'?'selected':''?>>Active</option><option value="pending" <?=$customer['status']==='pending'?'selected':''?>>Pending</option><option value="suspended" <?=$customer['status']==='suspended'?'selected':''?>>Suspended</option><option value="closed" <?=$customer['status']==='closed'?'selected':''?>>Closed</option></select><button class="outline">Update status</button></form></div><div><h3>Balance adjustment</h3><?=form_open('admin/customers/'.$customer['id'].'/adjust',array('class'=>'inline-controls'))?><select name="account_id"><?php foreach($customer['accounts'] as $a):?><option value="<?=$a['id']?>"><?=html_escape($a['name'])?> •<?=substr($a['account_number'],-4)?></option><?php endforeach?></select><select name="direction"><option value="credit">Credit</option><option value="debit">Debit</option></select><input type="number" name="amount" step="0.01" min="0.01" placeholder="Amount" required><input name="note" placeholder="Adjustment note"><button class="btn">Apply</button></form></div><div><h3>KYC verification</h3><?=form_open('admin/customers/'.$customer['id'].'/kyc',array('class'=>'inline-controls'))?><select name="kyc_status"><option value="pending" <?=$customer['kyc_status']==='pending'?'selected':''?>>Pending</option><option value="verified" <?=$customer['kyc_status']==='verified'?'selected':''?>>Verified</option><option value="rejected" <?=$customer['kyc_status']==='rejected'?'selected':''?>>Rejected</option></select><span class="kyc-badge kyc-<?=html_escape($customer['kyc_status'])?>"><?=ucfirst($customer['kyc_status'])?></span><button class="outline">Update KYC</button></form></div></section><div class="stats"><?php foreach($customer['accounts'] as $a):?><div><i>▣</i><span><?=html_escape($a['name'])?><b><?=money($a['available_balance'])?></b><small><?=$a['account_number']?></small></span></div><?php endforeach?></div><section class="panel"><div class="panel-head"><div><h2>Recent transactions</h2><p>Customer account activity</p></div></div><div class="data-table transaction-table"><div class="tr th"><span>Transaction</span><span>Date</span><span>Account</span><span>Amount</span><span>Status</span></div><?php foreach($customer['transactions'] as $t):?><div class="tr"><span class="name"><i><?=transaction_icon($t['type'])?></i><b><?=html_escape($t['description'])?><small><?=$t['reference']?></small></b></span><span><?=date('M j, Y',strtotime($t['transaction_date']))?></span><span>•••• <?=substr($t['account_number'],-4)?></span><strong class="<?=$t['type']?>"><?=money($t['amount'])?></strong><span class="<?=status_class($t['status'])?>"><?=ucfirst($t['status'])?></span></div><?php endforeach?></div></section>
